import React, { useEffect, useState } from "react";
import { Helmet } from "react-helmet-async";

import {
  FiBookOpen,
  FiClock,
  FiUsers,
  FiArrowRight,
  FiCheckCircle,
  FiX,
} from "react-icons/fi";

import api from "../../services/api";
import { getImageUrl } from "../../utils/helpers";
import { useLanguage } from "../../context/LanguageContext";

// =====================================================
// BRAND COLORS (ដូចគ្នានឹង Home.jsx)
// =====================================================
const COLORS = {
  blue: "#143DAA",
  red: "#EF233C",
  white: "#FFFFFF",
  darkText: "#1F2937",
  lightBg: "#F8FAFC",
};

const Courses = () => {
  // =====================================================
  // SCROLL TO TOP WHEN PAGE LOADS
  // =====================================================
  useEffect(() => {
    window.scrollTo({
      top: 0,
      behavior: "smooth", // រមូរដោយរលូន
    });
  }, []); // [] មានន័យថាដំណើរការតែម្តងគត់នៅពេលទំព័រផ្ទុកដំបូង

  // =====================================================
  // LANGUAGE
  // =====================================================
  const { t, language } = useLanguage();

  const isKhmer = language === "km";

  // =====================================================
  // STATE
  // =====================================================
  const [courses, setCourses] = useState([]);
  const [loading, setLoading] = useState(true);

  const [selectedCourse, setSelectedCourse] = useState(null);

  const [enrollSubmitting, setEnrollSubmitting] = useState(false);

  const [enrollSuccess, setEnrollSuccess] = useState("");

  const [enrollError, setEnrollError] = useState("");

  const initialEnrollForm = {
    khmer_name: "",
    english_name: "",
    gender: "",
    age: "",
    date_of_birth: "",
    nationality: "",
    nation: "",
    religion: "",
    state_id_no: "",
    issued_on: "",
    expired_on: "",
    house_no: "",
    village: "",
    commune_sangkat: "",
    district_khan: "",
    province_city: "",
    phone: "",
    email: "",
  };

  const [enrollForm, setEnrollForm] = useState(initialEnrollForm);

  // =====================================================
  // TRANSLATION FALLBACK
  // =====================================================
  const tr = (key, english, khmer) => {
    const value = t(key);

    if (value && value !== key) {
      return value;
    }

    return isKhmer ? khmer : english;
  };

  // =====================================================
  // LOCALIZED API FIELD
  // =====================================================
  const localized = (item, field, defaultValue = "") => {
    if (!item) {
      return defaultValue;
    }

    const selectedField = `${field}_${language}`;
    const englishField = `${field}_en`;
    const khmerField = `${field}_km`;

    if (
      item[selectedField] !== undefined &&
      item[selectedField] !== null &&
      String(item[selectedField]).trim() !== ""
    ) {
      return item[selectedField];
    }

    if (
      isKhmer &&
      item[englishField] !== undefined &&
      item[englishField] !== null &&
      String(item[englishField]).trim() !== ""
    ) {
      return item[englishField];
    }

    if (
      !isKhmer &&
      item[khmerField] !== undefined &&
      item[khmerField] !== null &&
      String(item[khmerField]).trim() !== ""
    ) {
      return item[khmerField];
    }

    if (
      item[field] !== undefined &&
      item[field] !== null &&
      String(item[field]).trim() !== ""
    ) {
      return item[field];
    }

    return defaultValue;
  };

  // =====================================================
  // FETCH COURSES
  // =====================================================
  useEffect(() => {
    fetchCourses();
  }, []);

  const fetchCourses = async () => {
    try {
      setLoading(true);

      const response = await api.get("/api/courses/");

      const data = Array.isArray(response.data)
        ? response.data
        : Array.isArray(response.data?.items)
        ? response.data.items
        : [];

      setCourses(data);
    } catch (error) {
      console.error("Error fetching courses:", error);

      setCourses([]);
    } finally {
      setLoading(false);
    }
  };

  // =====================================================
  // COURSE FEATURES
  // Supports:
  // features_en
  // features_km
  // features
  // Array or comma-separated string
  // =====================================================
  const getCourseFeatures = (course) => {
    if (!course) {
      return [];
    }

    let featuresValue = null;

    if (language === "km" && course.features_km) {
      featuresValue = course.features_km;
    } else if (language === "en" && course.features_en) {
      featuresValue = course.features_en;
    } else if (course.features) {
      featuresValue = course.features;
    } else if (course.features_en) {
      featuresValue = course.features_en;
    } else if (course.features_km) {
      featuresValue = course.features_km;
    }

    if (!featuresValue) {
      return [];
    }

    if (Array.isArray(featuresValue)) {
      return featuresValue.map((item) => String(item).trim()).filter(Boolean);
    }

    return String(featuresValue)
      .split(",")
      .map((item) => item.trim())
      .filter(Boolean);
  };

  // =====================================================
  // COURSE IMAGE
  // =====================================================
  const getCourseImage = (course) => {
    return course?.image_url || course?.image || course?.thumbnail || "";
  };

  // =====================================================
  // WHY CHOOSE DATA
  // =====================================================
  const features = [
    {
      icon: FiBookOpen,

      title: tr(
        "courses.practicalLearning",
        "Practical Learning",
        "ការសិក្សាអនុវត្តជាក់ស្តែង"
      ),

      description: tr(
        "courses.practicalLearningDescription",
        "Learn through practical lessons and real-world exercises.",
        "រៀនតាមរយៈមេរៀនអនុវត្ត និងលំហាត់ដែលទាក់ទងនឹងការប្រើប្រាស់ជាក់ស្តែង។"
      ),
    },

    {
      icon: FiUsers,

      title: tr(
        "courses.expertTeachers",
        "Expert Teachers",
        "គ្រូបង្រៀនមានបទពិសោធន៍"
      ),

      description: tr(
        "courses.expertTeachersDescription",
        "Learn with experienced and supportive instructors.",
        "សិក្សាជាមួយគ្រូបង្រៀនដែលមានបទពិសោធន៍ និងតែងតែគាំទ្រដល់ការសិក្សារបស់អ្នក។"
      ),
    },

    {
      icon: FiClock,

      title: tr(
        "courses.flexibleSchedule",
        "Flexible Schedule",
        "កាលវិភាគបត់បែន"
      ),

      description: tr(
        "courses.flexibleScheduleDescription",
        "Choose a learning schedule that works best for you.",
        "ជ្រើសរើសកាលវិភាគសិក្សាដែលសមស្របបំផុតសម្រាប់អ្នក។"
      ),
    },

    {
      icon: FiCheckCircle,

      title: tr(
        "courses.qualityPrograms",
        "Quality Programs",
        "កម្មវិធីសិក្សាមានគុណភាព"
      ),

      description: tr(
        "courses.qualityProgramsDescription",
        "Programs designed to build useful skills and knowledge.",
        "វគ្គសិក្សាត្រូវបានរៀបចំឡើងដើម្បីអភិវឌ្ឍជំនាញ និងចំណេះដឹងដែលមានប្រយោជន៍។"
      ),
    },
  ];

  // =====================================================
  // SCROLL TO COURSES
  // =====================================================
  const scrollToCourses = () => {
    const section = document.getElementById("courses-section");

    if (section) {
      section.scrollIntoView({
        behavior: "smooth",
        block: "start",
      });
    }
  };

  // =====================================================
  // OPEN ENROLL MODAL
  // =====================================================
  const openEnrollModal = (course) => {
    setSelectedCourse(course);

    setEnrollSuccess("");
    setEnrollError("");

    setEnrollForm(initialEnrollForm);

    document.body.style.overflow = "hidden";
  };

  // =====================================================
  // CLOSE ENROLL MODAL
  // =====================================================
  const closeEnrollModal = () => {
    if (enrollSubmitting) {
      return;
    }

    setSelectedCourse(null);

    setEnrollSuccess("");
    setEnrollError("");

    document.body.style.overflow = "auto";
  };

  // =====================================================
  // CLEAN BODY OVERFLOW
  // =====================================================
  useEffect(() => {
    return () => {
      document.body.style.overflow = "auto";
    };
  }, []);

  // =====================================================
  // API ERROR MESSAGE
  // =====================================================
  const getApiErrorMessage = (error, fallback) => {
    const detail = error?.response?.data?.detail;

    if (Array.isArray(detail)) {
      return detail.map((item) => item?.msg || item).filter(Boolean).join(", ");
    }

    return detail || error?.response?.data?.message || error?.message || fallback;
  };

  // =====================================================
  // ENROLL SUBMIT
  // =====================================================
  const handleEnrollSubmit = async (event) => {
    event.preventDefault();

    if (!selectedCourse?.id) {
      setEnrollError(
        tr(
          "enrollment.selectCourseError",
          "Please select a course.",
          "សូមជ្រើសរើសវគ្គសិក្សា។"
        )
      );

      return;
    }

    try {
      setEnrollSubmitting(true);
      setEnrollError("");
      setEnrollSuccess("");

      await api.post("/api/enrollments/", {
        ...enrollForm,
        course_id: selectedCourse.id,
      });

      setEnrollSuccess(
        tr(
          "enrollment.success",
          "Enrollment submitted successfully. Our team will contact you soon.",
          "ការចុះឈ្មោះរបស់អ្នកត្រូវបានផ្ញើដោយជោគជ័យ។ ក្រុមការងាររបស់យើងនឹងទាក់ទងទៅអ្នកឆាប់ៗនេះ។"
        )
      );

      setEnrollForm(initialEnrollForm);
    } catch (error) {
      console.error("Enrollment error:", error);

      setEnrollError(
        getApiErrorMessage(
          error,
          tr(
            "enrollment.error",
            "Failed to submit enrollment. Please try again.",
            "ការផ្ញើការចុះឈ្មោះមិនបានជោគជ័យ។ សូមព្យាយាមម្តងទៀត។"
          )
        )
      );
    } finally {
      setEnrollSubmitting(false);
    }
  };

  // =====================================================
  // RETURN
  // =====================================================
  return (
    <>
      {/* =================================================
          SEO
      ================================================= */}
      <Helmet>
        <title>
          {tr(
            "courses.pageTitle",
            "SC Academy Programs | Learn and Grow",
            "វគ្គសិក្សា SC Academy | រៀន និងអភិវឌ្ឍ"
          )}
        </title>

        <meta
          name="description"
          content={tr(
            "courses.seoDescription",
            "Explore available programs and learning programs at SC Academy.",
            "ស្វែងយល់ពីវគ្គសិក្សា និងកម្មវិធីសិក្សាដែលមាននៅ SC Academy។"
          )}
        />
      </Helmet>

      {/* =================================================
          HERO (UPDATED COLORS TO MATCH HOME)
      ================================================= */}
      <section
        className={`
          relative
          h-[400px]
          md:h-[430px]
          lg:h-[450px]
          overflow-hidden
          bg-[#143DAA] /* UPDATED: Blue Brand Color */
          text-white
          ${isKhmer ? "font-khmer" : ""}
        `}
      >
        {/* BACKGROUND GRADIENT */}
        <div className="absolute inset-0 bg-gradient-to-r from-[#143DAA] via-[#143DAA] to-[#143DAA]" />

        {/* TOP RIGHT DECORATION */}
        <div className="absolute -top-24 -right-20 w-[350px] h-[350px] bg-[#EF233C]/10 rounded-full blur-3xl pointer-events-none" />

        {/* BOTTOM LEFT DECORATION */}
        <div className="absolute -bottom-28 -left-20 w-[320px] h-[320px] bg-white/5 rounded-full blur-3xl pointer-events-none" />

        {/* BOTTOM ACCENT LINE */}
        <div className="absolute bottom-0 left-0 right-0 z-20 h-[4px] bg-[#EF233C]" />

        {/* CONTENT */}
        <div className="relative z-10 w-full max-w-[1120px] mx-auto px-4 h-full flex items-center">
          <div className="max-w-[680px]">
            {/* LABEL */}
            <div className="flex items-center gap-2 text-red-400 text-[12px] md:text-[13px] font-semibold mb-3">
              <span className="w-7 h-[2px] bg-[#EF233C] rounded-full" />

              {tr("courses.heroLabel", "Our Programs", "វគ្គសិក្សារបស់យើង")}
            </div>

            {/* TITLE */}
            <h1 className="text-[30px] sm:text-[34px] md:text-[40px] lg:text-[44px] font-bold text-white leading-[1.4] mb-4">
              {tr(
                "courses.heroTitle",
                "Learn, Grow & Build Your Future",
                "រៀន អភិវឌ្ឍ និងកសាងអនាគតរបស់អ្នក"
              )}
            </h1>

            {/* ACCENT */}
            <div className="flex items-center gap-2 mb-4">
              <span className="w-10 h-[3px] bg-[#EF233C] rounded-full" />
              <span className="w-4 h-[3px] bg-white/30 rounded-full" />
            </div>

            {/* DESCRIPTION */}
            <p className="text-[14px] md:text-[15px] text-white/60 leading-7 max-w-[600px]">
              {tr(
                "courses.heroDescription",
                "Choose the right program for your goals and develop the knowledge and practical skills you need for your future.",
                "ជ្រើសរើសកម្មវិធីសិក្សាដែលសមស្របនឹងគោលដៅរបស់អ្នក និងអភិវឌ្ឍចំណេះដឹង និងជំនាញអនុវត្តដែលអ្នកត្រូវការសម្រាប់អនាគត។"
              )}
            </p>
          </div>
        </div>
      </section>

      {/* =================================================
          COURSES SECTION
      ================================================= */}
      <section
        id="courses-section"
        className={`
          bg-[#F8FAFC] /* UPDATED: Light Background Color */
          py-16 md:py-20
          ${isKhmer ? "font-khmer" : ""}
        `}
      >
        <div className="w-full max-w-[1120px] mx-auto px-4">
          {/* TOP SECTION LINE */}
          <div className="flex items-center gap-4 mb-7">
            <h2 className="text-[13px] font-bold text-[#143DAA] whitespace-nowrap">
              {tr("courses.ourCourses", "Our Programs", "វគ្គសិក្សារបស់យើង")}
            </h2>

            <div className="h-px bg-[#143DAA]/20 flex-1" />
          </div>

          {/* =================================================
              INTRO
          ================================================= */}
          <div className="text-center max-w-[650px] mx-auto mb-8">
            <span className="text-[#EF233C] text-[9px] font-bold uppercase tracking-[0.15em]">
              {tr(
                "courses.explorePrograms",
                "Explore Our Programs",
                "ស្វែងយល់ពីកម្មវិធីសិក្សារបស់យើង"
              )}
            </span>

            <h2 className="text-[20px] md:text-[24px] font-bold text-[#143DAA] mt-2">
              {tr("courses.popular", "Popular Programs", "វគ្គសិក្សាពេញនិយម")}
            </h2>

            {/* ACCENT */}
            <div className="flex items-center justify-center gap-2 mt-3">
              <span className="w-10 h-[3px] bg-[#EF233C] rounded-full" />
              <span className="w-4 h-[3px] bg-[#143DAA]/20 rounded-full" />
            </div>

            <p className="text-[11px] md:text-[12px] text-[#1F2937] leading-6 mt-3">
              {tr(
                "courses.introDescription",
                "Our programs are designed to help students build practical knowledge, confidence and useful skills for education and future careers.",
                "វគ្គសិក្សារបស់យើងត្រូវបានរៀបចំឡើងដើម្បីជួយសិស្សអភិវឌ្ឍចំណេះដឹងអនុវត្ត ទំនុកចិត្ត និងជំនាញដែលមានប្រយោជន៍សម្រាប់ការសិក្សា និងអាជីពនាពេលអនាគត។"
              )}
            </p>
          </div>

          {/* =================================================
              LOADING
          ================================================= */}
          {loading ? (
            <div className="py-16 flex flex-col items-center justify-center">
              <div className="w-10 h-10 rounded-full border-[3px] border-[#143DAA]/20 border-t-[#143DAA] animate-spin" />

              <p className="mt-3 text-[11px] text-[#1F2937]/60 font-medium">
                {tr(
                  "courses.loading",
                  "Loading programs...",
                  "កំពុងផ្ទុកវគ្គសិក្សា..."
                )}
              </p>
            </div>
          ) : courses.length === 0 ? (
            /* =================================================
                EMPTY
            ================================================= */
            <div className="max-w-[500px] mx-auto bg-white border border-[#143DAA]/10 rounded-xl py-10 px-5 text-center shadow-lg shadow-[#143DAA]/5">
              <div className="w-12 h-12 mx-auto mb-3 bg-[#F8FAFC] rounded-xl flex items-center justify-center">
                <FiBookOpen size={21} className="text-[#143DAA]" />
              </div>

              <h3 className="text-[14px] font-bold text-[#143DAA]">
                {tr("courses.noCourses", "No Programs Available", "មិនមានវគ្គសិក្សា")}
              </h3>

              <p className="text-[10px] md:text-[11px] text-[#1F2937]/70 mt-2">
                {tr(
                  "courses.noCoursesDescription",
                  "New programs will be available soon.",
                  "វគ្គសិក្សាថ្មីៗនឹងមានក្នុងពេលឆាប់ៗនេះ។"
                )}
              </p>
            </div>
          ) : (
            /* =================================================
                COURSE GRID (UPDATED COLORS)
            ================================================= */
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
              {courses.map((course, index) => {
                const courseImage = getCourseImage(course);

                const courseFeatures = getCourseFeatures(course);

                const courseTitle = localized(
                  course,
                  "title",
                  tr(
                    "courses.defaultTitle",
                    "SC Academy Program",
                    "វគ្គសិក្សា SC Academy"
                  )
                );

                const courseDescription = localized(
                  course,
                  "description",
                  tr(
                    "courses.defaultDescription",
                    "Learn practical knowledge and skills with SC Academy.",
                    "សិក្សាចំណេះដឹង និងជំនាញអនុវត្តជាមួយ SC Academy។"
                  )
                );

                const courseLevel = localized(
                  course,
                  "level",
                  tr("courses.allLevels", "All Levels", "គ្រប់កម្រិត")
                );

                const courseDuration = localized(
                  course,
                  "duration",
                  tr("courses.flexible", "Flexible", "បត់បែន")
                );

                return (
                  <article
                    key={course.id || index}
                    className="
                      group
                      bg-white
                      border
                      border-[#143DAA]/10
                      rounded-xl
                      overflow-hidden
                      shadow-lg shadow-[#143DAA]/5
                      hover:shadow-xl hover:shadow-[#143DAA]/15 hover:-translate-y-1
                      transition-all
                      duration-300
                      flex
                      flex-col
                    "
                  >
                    {/* =====================================
                        COURSE IMAGE
                    ====================================== */}
                    <div className="relative w-full h-[165px] sm:h-[175px] bg-[#F8FAFC] overflow-hidden">
                      {/* FALLBACK */}
                      <div className="absolute inset-0 bg-gradient-to-br from-[#143DAA] to-[#143DAA] flex flex-col items-center justify-center">
                        <div className="w-10 h-10 bg-white/10 rounded-xl flex items-center justify-center text-white">
                          <FiBookOpen size={18} />
                        </div>

                        <span className="text-[8px] text-white/40 font-semibold mt-2">
                          SC Academy
                        </span>
                      </div>

                      {/* IMAGE */}
                      {courseImage && (
                        <img
                          src={getImageUrl(courseImage)}
                          alt={courseTitle}
                          className="
                            relative
                            z-[1]
                            w-full
                            h-full
                            object-cover
                            group-hover:scale-105
                            transition-transform
                            duration-500
                          "
                          onError={(event) => {
                            event.currentTarget.style.display = "none";
                          }}
                        />
                      )}

                      {/* GRADIENT */}
                      <div className="absolute inset-0 z-[2] bg-gradient-to-t from-[#143DAA]/45 via-transparent to-transparent pointer-events-none" />

                      {/* LEVEL BADGE */}
                      <div className="absolute top-3 left-3 z-[4]">
                        <span className="inline-flex items-center h-[22px] px-2.5 bg-[#EF233C] text-white text-[8px] font-bold rounded-full shadow-sm">
                          {courseLevel}
                        </span>
                      </div>

                      {/* COURSE NUMBER */}
                      <div className="absolute bottom-3 right-3 z-[4] w-8 h-8 bg-[#143DAA]/90 border border-white/10 text-white rounded-md flex items-center justify-center text-[9px] font-bold shadow-sm">
                        {String(index + 1).padStart(2, "0")}
                      </div>

                      {/* BOTTOM ACCENT */}
                      <div className="absolute bottom-0 left-0 right-0 z-[5] h-[3px] bg-[#EF233C]" />
                    </div>

                    {/* =====================================
                        CARD CONTENT
                    ====================================== */}
                    <div className="px-4 py-3.5 flex flex-col flex-grow">
                      {/* SMALL LABEL */}
                      <span className="text-[#EF233C] text-[7px] font-bold uppercase tracking-[0.14em]">
                        {tr(
                          "courses.courseLabel",
                          "SC Academy Program",
                          "វគ្គសិក្សា SC Academy"
                        )}
                      </span>

                      {/* TITLE */}
                      <h3 className="text-[13px] md:text-[14px] font-bold text-[#143DAA] leading-[20px] mt-1 line-clamp-2">
                        {courseTitle}
                      </h3>

                      {/* ACCENT */}
                      <div className="flex items-center gap-1.5 mt-2 mb-2.5">
                        <span className="w-7 h-[2px] bg-[#EF233C] rounded-full" />
                        <span className="w-3 h-[2px] bg-[#143DAA]/20 rounded-full" />
                      </div>

                      {/* DESCRIPTION */}
                      <p className="text-[9px] md:text-[10px] text-[#1F2937] leading-[18px] line-clamp-2 mb-3">
                        {courseDescription}
                      </p>

                      {/* =====================================
                          DURATION + LEVEL
                      ====================================== */}
                      <div className="grid grid-cols-2 gap-2 mb-3">
                        {/* DURATION */}
                        <div className="bg-[#F8FAFC] border border-[#143DAA]/10 rounded-md px-2.5 py-2">
                          <div className="flex items-center gap-1.5">
                            <FiClock size={10} className="text-[#EF233C]" />

                            <span className="text-[7px] font-bold uppercase tracking-wide text-[#143DAA]">
                              {tr("courses.duration", "Duration", "រយៈពេល")}
                            </span>
                          </div>

                          <p className="text-[9px] md:text-[10px] font-semibold text-[#1F2937] mt-1 truncate">
                            {courseDuration}
                          </p>
                        </div>

                        {/* LEVEL */}
                        <div className="bg-[#F8FAFC] border border-[#143DAA]/10 rounded-md px-2.5 py-2">
                          <div className="flex items-center gap-1.5">
                            <FiUsers size={10} className="text-[#EF233C]" />

                            <span className="text-[7px] font-bold uppercase tracking-wide text-[#143DAA]">
                              {tr("courses.level", "Level", "កម្រិត")}
                            </span>
                          </div>

                          <p className="text-[9px] md:text-[10px] font-semibold text-[#1F2937] mt-1 truncate">
                            {courseLevel}
                          </p>
                        </div>
                      </div>

                      {/* =====================================
                          FEATURES
                      ====================================== */}
                      {courseFeatures.length > 0 && (
                        <div className="mb-3">
                          <h4 className="text-[8px] font-bold text-[#143DAA] uppercase tracking-wider mb-1.5">
                            {tr(
                              "courses.whatYouLearn",
                              "What You'll Learn",
                              "អ្វីដែលអ្នកនឹងរៀន"
                            )}
                          </h4>

                          <div className="space-y-1">
                            {courseFeatures.slice(0, 2).map((feature, featureIndex) => (
                              <div key={featureIndex} className="flex items-start text-[8px] md:text-[9px] text-[#1F2937] leading-4">
                                <FiCheckCircle size={10} className="text-[#EF233C] mr-1.5 mt-[2px] flex-shrink-0" />

                                <span className="line-clamp-1">{feature}</span>
                              </div>
                            ))}
                          </div>
                        </div>
                      )}

                      {/* =====================================
                          PRICE
                      ====================================== */}
                      {course.price !== null &&
                        course.price !== undefined &&
                        course.price !== "" && (
                          <div className="flex items-center justify-between bg-[#F8FAFC] border border-[#143DAA]/10 rounded-md px-3 py-2 mb-3">
                            <span className="text-[7px] font-bold uppercase tracking-wide text-[#1F2937]/60">
                              {tr("courses.courseFee", "Program Fee", "តម្លៃវគ្គសិក្សា")}
                            </span>

                            <span className="text-[13px] font-bold text-[#143DAA]">${course.price}</span>
                          </div>
                        )}

                      <div className="flex-grow" />

                      <div className="h-px bg-[#143DAA]/10 mb-3" />

                      {/* =====================================
                          ENROLL BUTTON
                      ====================================== */}
                      <button
                        type="button"
                        onClick={() => openEnrollModal(course)}
                        className="
                          w-full
                          h-[34px]
                          bg-[#143DAA]
                          hover:bg-[#EF233C]
                          text-white
                          rounded-md
                          text-[9px]
                          md:text-[10px]
                          font-bold
                          flex
                          items-center
                          justify-center
                          transition-all
                          duration-300
                          group/button
                        "
                      >
                        {tr("courses.enroll", "Enroll Program", "ចុះឈ្មោះវគ្គសិក្សា")}

                        <FiArrowRight
                          size={11}
                          className="
                            ml-2
                            group-hover/button:translate-x-1
                            transition-transform
                          "
                        />
                      </button>
                    </div>
                  </article>
                );
              })}
            </div>
          )}
        </div>
      </section>

      {/* =================================================
          WHY CHOOSE SC ACADEMY (UPDATED COLORS)
      ================================================= */}
      <section
        className={`
          bg-white
          py-14 md:py-16
          ${isKhmer ? "font-khmer" : ""}
        `}
      >
        <div className="w-full max-w-[1120px] mx-auto px-4">
          {/* TOP LINE */}
          <div className="flex items-center gap-4 mb-7">
            <h2 className="text-[13px] font-bold text-[#143DAA] whitespace-nowrap">
              {tr("courses.whyAcademy", "Why SC Academy", "ហេតុអ្វីជ្រើសរើស SC Academy")}
            </h2>

            <div className="h-px bg-[#143DAA]/20 flex-1" />
          </div>

          {/* HEADER */}
          <div className="text-center max-w-[650px] mx-auto mb-8">
            <span className="text-[#EF233C] text-[9px] font-bold uppercase tracking-[0.15em]">
              {tr(
                "courses.whyChoose",
                "Why Choose Our Programs",
                "ហេតុអ្វីជ្រើសរើសវគ្គសិក្សារបស់យើង"
              )}
            </span>

            <h2 className="text-[20px] md:text-[24px] font-bold text-[#143DAA] mt-2">
              {tr("courses.learnConfidence", "Learn With Confidence", "សិក្សាដោយទំនុកចិត្ត")}
            </h2>

            {/* ACCENT */}
            <div className="flex items-center justify-center gap-2 mt-3">
              <span className="w-10 h-[3px] bg-[#EF233C] rounded-full" />
              <span className="w-4 h-[3px] bg-[#143DAA]/20 rounded-full" />
            </div>

            <p className="text-[11px] md:text-[12px] text-[#1F2937] leading-6 mt-3">
              {tr(
                "courses.whyDescription",
                "Our learning programs combine practical skills, experienced instructors and a supportive learning environment.",
                "កម្មវិធីសិក្សារបស់យើងរួមបញ្ចូលជំនាញអនុវត្ត គ្រូបង្រៀនដែលមានបទពិសោធន៍ និងបរិយាកាសសិក្សាដែលផ្តល់ការគាំទ្រ។"
              )}
            </p>
          </div>

          {/* FEATURE CARDS */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            {features.map((feature, index) => {
              const Icon = feature.icon;

              return (
                <article
                  key={index}
                  className="
                    group
                    relative
                    bg-white
                    border
                    border-[#143DAA]/10
                    rounded-xl
                    px-4
                    py-4
                    text-center
                    shadow-md shadow-[#143DAA]/5
                    hover:shadow-lg hover:shadow-[#143DAA]/15 hover:-translate-y-1
                    overflow-hidden
                    transition-all
                    duration-300
                  "
                >
                  <div className="absolute top-0 left-0 right-0 h-[3px] bg-[#EF233C]" />

                  {/* ICON */}
                  <div className="w-10 h-10 mx-auto bg-[#F8FAFC] rounded-xl flex items-center justify-center text-[#143DAA] group-hover:bg-[#143DAA] group-hover:text-white transition-colors duration-300">
                    <Icon size={16} />
                  </div>

                  {/* TITLE */}
                  <h3 className="text-[12px] md:text-[13px] font-bold text-[#143DAA] mt-3">{feature.title}</h3>

                  {/* ACCENT */}
                  <div className="flex items-center justify-center gap-1.5 mt-2">
                    <span className="w-6 h-[2px] bg-[#EF233C] rounded-full" />
                    <span className="w-2 h-[2px] bg-[#143DAA]/20 rounded-full" />
                  </div>

                  {/* DESCRIPTION */}
                  <p className="text-[9px] md:text-[10px] text-[#1F2937] leading-5 mt-2">
                    {feature.description}
                  </p>
                </article>
              );
            })}
          </div>
        </div>
      </section>

      {/* =================================================
          CTA (UPDATED COLORS)
      ================================================= */}
      <section
        className={`
          bg-[#F8FAFC] /* UPDATED: Light Background */
          py-14 md:py-16
          ${isKhmer ? "font-khmer" : ""}
        `}
      >
        <div className="w-full max-w-[1120px] mx-auto px-4">
          <div className="max-w-[650px] mx-auto text-center">
            {/* LABEL */}
            <span className="text-[#EF233C] text-[9px] font-bold uppercase tracking-[0.15em]">
              {tr("courses.startToday", "Start Learning Today", "ចាប់ផ្តើមសិក្សាថ្ងៃនេះ")}
            </span>

            {/* TITLE */}
            <h2 className="text-[22px] md:text-[28px] font-bold text-[#143DAA] mt-2">
              {tr("courses.readyBuild", "Ready to Build Your", "ត្រៀមខ្លួនដើម្បីកសាង")}{" "}
              <span className="text-[#EF233C]">{tr("courses.future", "Future?", "អនាគតរបស់អ្នក?")}</span>
            </h2>

            {/* ACCENT */}
            <div className="flex items-center justify-center gap-2 mt-3">
              <span className="w-10 h-[3px] bg-[#EF233C] rounded-full" />
              <span className="w-4 h-[3px] bg-[#143DAA]/20 rounded-full" />
            </div>

            {/* DESCRIPTION */}
            <p className="text-[11px] md:text-[12px] text-[#1F2937] leading-6 max-w-[580px] mx-auto mt-4">
              {tr(
                "courses.ctaDescription",
                "Choose your program and start developing the knowledge and practical skills you need to achieve your goals.",
                "ជ្រើសរើសវគ្គសិក្សារបស់អ្នក ហើយចាប់ផ្តើមអភិវឌ្ឍចំណេះដឹង និងជំនាញអនុវត្តដែលអ្នកត្រូវការដើម្បីសម្រេចគោលដៅ។"
              )}
            </p>

            {/* BUTTON */}
            <button
              type="button"
              onClick={scrollToCourses}
              className="
                mt-5
                h-[36px]
                px-5
                bg-[#EF233C]
                hover:bg-[#D91A2A]
                text-white
                rounded-md
                inline-flex
                items-center
                justify-center
                text-[10px]
                font-bold
                transition-all
                duration-300
                group
              "
            >
              {tr("courses.exploreCourses", "Explore Programs", "ស្វែងយល់ពីវគ្គសិក្សា")}

              <FiArrowRight
                size={12}
                className="
                  ml-2
                  group-hover:translate-x-1
                  transition-transform
                "
              />
            </button>
          </div>
        </div>
      </section>

      {/* =================================================
          ENROLLMENT MODAL (UPDATED COLORS)
      ================================================= */}
      {selectedCourse && (
        <div
          className={`
            fixed
            inset-0
            z-50
            flex
            items-center
            justify-center
            bg-[#143DAA]/80 /* UPDATED: Brand Blue Overlay */
            px-4
            py-6
            ${isKhmer ? "font-khmer" : ""}
          `}
          onClick={closeEnrollModal}
        >
          <div
            className="relative w-full max-w-xl rounded-xl bg-white shadow-2xl max-h-[92vh] overflow-y-auto"
            onClick={(event) => event.stopPropagation()}
          >
            {/* CLOSE */}
            <button
              type="button"
              onClick={closeEnrollModal}
              disabled={enrollSubmitting}
              className="
                absolute
                right-4
                top-4
                w-9
                h-9
                rounded-xl
                bg-[#F8FAFC]
                text-[#143DAA]
                flex
                items-center
                justify-center
                hover:bg-[#EF233C]
                hover:text-white
                transition
                disabled:opacity-50
              "
              aria-label={tr(
                "enrollment.close",
                "Close enrollment form",
                "បិទទម្រង់ចុះឈ្មោះ"
              )}
            >
              <FiX size={18} />
            </button>

            {/* HEADER */}
            <div className="p-5 md:p-6 border-b border-[#143DAA]/10">
              <p className="text-[10px] font-bold uppercase tracking-[0.16em] text-[#EF233C]">
                {tr("enrollment.courseEnrollment", "Program Enrollment", "ការចុះឈ្មោះកម្មវិធី")}
              </p>

              <h2 className="mt-2 pr-10 text-xl md:text-2xl font-bold text-[#143DAA]">
                {localized(
                  selectedCourse,
                  "title",
                  tr(
                    "enrollment.selectedCourse",
                    "Selected Program",
                    "កម្មវិធីដែលបានជ្រើសរើស"
                  )
                )}
              </h2>

              <p className="mt-2 text-sm leading-6 text-[#1F2937]">
                {tr(
                  "enrollment.formDescription",
                  "Fill in your details and our team will contact you about this program.",
                  "សូមបំពេញព័ត៌មានរបស់អ្នក ហើយក្រុមការងាររបស់យើងនឹងទាក់ទងទៅអ្នកអំពីកម្មវិធីនេះ។"
                )}
              </p>
            </div>

            {/* FORM */}
            <form onSubmit={handleEnrollSubmit} className="p-5 md:p-6 space-y-4">
              {/* ERROR */}
              {enrollError && (
                <div className="rounded-xl border border-[#EF233C]/20 bg-[#EF233C]/5 px-4 py-3 text-sm font-medium text-[#EF233C]">
                  {enrollError}
                </div>
              )}

              {/* SUCCESS */}
              {enrollSuccess && (
                <div className="rounded-xl border border-[#143DAA]/10 bg-[#F8FAFC] px-4 py-3 text-sm font-medium text-[#143DAA]">
                  {enrollSuccess}
                </div>
              )}

              {/* STUDENT INFORMATION */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-semibold text-[#143DAA] mb-1.5">
                    {tr("enrollment.khmerName", "Khmer Name", "ឈ្មោះជាភាសាខ្មែរ")} *
                  </label>
                  <input
                    type="text"
                    value={enrollForm.khmer_name}
                    onChange={(event) =>
                      setEnrollForm({
                        ...enrollForm,
                        khmer_name: event.target.value,
                      })
                    }
                    className="w-full h-11 rounded-xl border border-[#143DAA]/20 px-3.5 text-sm text-[#143DAA] outline-none focus:border-[#143DAA] focus:ring-2 focus:ring-[#143DAA]/10"
                    required
                  />
                </div>

                <div>
                  <label className="block text-sm font-semibold text-[#143DAA] mb-1.5">
                    {tr("enrollment.englishName", "English Name", "ឈ្មោះជាភាសាអង់គ្លេស")} *
                  </label>
                  <input
                    type="text"
                    value={enrollForm.english_name}
                    onChange={(event) =>
                      setEnrollForm({
                        ...enrollForm,
                        english_name: event.target.value,
                      })
                    }
                    className="w-full h-11 rounded-xl border border-[#143DAA]/20 px-3.5 text-sm text-[#143DAA] outline-none focus:border-[#143DAA] focus:ring-2 focus:ring-[#143DAA]/10"
                    required
                  />
                </div>

                <div>
                  <label className="block text-sm font-semibold text-[#143DAA] mb-1.5">
                    {tr("enrollment.gender", "Gender", "ភេទ")} *
                  </label>
                  <select
                    value={enrollForm.gender}
                    onChange={(event) =>
                      setEnrollForm({
                        ...enrollForm,
                        gender: event.target.value,
                      })
                    }
                    className="w-full h-11 rounded-xl border border-[#143DAA]/20 px-3.5 text-sm text-[#143DAA] outline-none focus:border-[#143DAA] focus:ring-2 focus:ring-[#143DAA]/10"
                    required
                  >
                    <option value="">
                      {tr("enrollment.selectGender", "Select gender", "ជ្រើសរើសភេទ")}
                    </option>
                    <option value="male">
                      {tr("enrollment.male", "Male", "ប្រុស")}
                    </option>
                    <option value="female">
                      {tr("enrollment.female", "Female", "ស្រី")}
                    </option>
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-semibold text-[#143DAA] mb-1.5">
                    {tr("enrollment.age", "Age", "អាយុ")}
                  </label>
                  <input
                    type="number"
                    min="1"
                    value={enrollForm.age}
                    onChange={(event) =>
                      setEnrollForm({
                        ...enrollForm,
                        age: event.target.value,
                      })
                    }
                    className="w-full h-11 rounded-xl border border-[#143DAA]/20 px-3.5 text-sm text-[#143DAA] outline-none focus:border-[#143DAA] focus:ring-2 focus:ring-[#143DAA]/10"
                  />
                </div>

                <div>
                  <label className="block text-sm font-semibold text-[#143DAA] mb-1.5">
                    {tr("enrollment.dateOfBirth", "Date of Birth", "ថ្ងៃ ខែ ឆ្នាំកំណើត")}
                  </label>
                  <input
                    type="date"
                    value={enrollForm.date_of_birth}
                    onChange={(event) =>
                      setEnrollForm({
                        ...enrollForm,
                        date_of_birth: event.target.value,
                      })
                    }
                    className="w-full h-11 rounded-xl border border-[#143DAA]/20 px-3.5 text-sm text-[#143DAA] outline-none focus:border-[#143DAA] focus:ring-2 focus:ring-[#143DAA]/10"
                  />
                </div>

                <div>
                  <label className="block text-sm font-semibold text-[#143DAA] mb-1.5">
                    {tr("enrollment.nationality", "Nationality", "សញ្ជាតិ")}
                  </label>
                  <input
                    type="text"
                    value={enrollForm.nationality}
                    onChange={(event) =>
                      setEnrollForm({
                        ...enrollForm,
                        nationality: event.target.value,
                      })
                    }
                    className="w-full h-11 rounded-xl border border-[#143DAA]/20 px-3.5 text-sm text-[#143DAA] outline-none focus:border-[#143DAA] focus:ring-2 focus:ring-[#143DAA]/10"
                  />
                </div>

                <div>
                  <label className="block text-sm font-semibold text-[#143DAA] mb-1.5">
                    {tr("enrollment.nation", "Nation", "ជាតិ")}
                  </label>
                  <input
                    type="text"
                    value={enrollForm.nation}
                    onChange={(event) =>
                      setEnrollForm({
                        ...enrollForm,
                        nation: event.target.value,
                      })
                    }
                    className="w-full h-11 rounded-xl border border-[#143DAA]/20 px-3.5 text-sm text-[#143DAA] outline-none focus:border-[#143DAA] focus:ring-2 focus:ring-[#143DAA]/10"
                  />
                </div>

                <div>
                  <label className="block text-sm font-semibold text-[#143DAA] mb-1.5">
                    {tr("enrollment.religion", "Religion", "សាសនា")}
                  </label>
                  <input
                    type="text"
                    value={enrollForm.religion}
                    onChange={(event) =>
                      setEnrollForm({
                        ...enrollForm,
                        religion: event.target.value,
                      })
                    }
                    className="w-full h-11 rounded-xl border border-[#143DAA]/20 px-3.5 text-sm text-[#143DAA] outline-none focus:border-[#143DAA] focus:ring-2 focus:ring-[#143DAA]/10"
                  />
                </div>
              </div>

              <div className="border-t border-[#143DAA]/10 pt-4">
                <h3 className="text-sm font-bold text-[#143DAA] mb-3">
                  {tr("enrollment.nationalIdInfo", "National ID Information", "ព័ត៌មានអត្តសញ្ញាណប័ណ្ណ")}
                </h3>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <div>
                    <label className="block text-sm font-semibold text-[#143DAA] mb-1.5">
                      {tr("enrollment.stateIdNo", "State ID No.", "លេខអត្តសញ្ញាណប័ណ្ណ")}
                    </label>
                    <input
                      type="text"
                      value={enrollForm.state_id_no}
                      onChange={(event) =>
                        setEnrollForm({
                          ...enrollForm,
                          state_id_no: event.target.value,
                        })
                      }
                      className="w-full h-11 rounded-xl border border-[#143DAA]/20 px-3.5 text-sm text-[#143DAA] outline-none focus:border-[#143DAA] focus:ring-2 focus:ring-[#143DAA]/10"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-semibold text-[#143DAA] mb-1.5">
                      {tr("enrollment.issuedOn", "Issued On", "ចេញថ្ងៃទី")}
                    </label>
                    <input
                      type="date"
                      value={enrollForm.issued_on}
                      onChange={(event) =>
                        setEnrollForm({
                          ...enrollForm,
                          issued_on: event.target.value,
                        })
                      }
                      className="w-full h-11 rounded-xl border border-[#143DAA]/20 px-3.5 text-sm text-[#143DAA] outline-none focus:border-[#143DAA] focus:ring-2 focus:ring-[#143DAA]/10"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-semibold text-[#143DAA] mb-1.5">
                      {tr("enrollment.expiredOn", "Expired On", "ផុតកំណត់ថ្ងៃទី")}
                    </label>
                    <input
                      type="date"
                      value={enrollForm.expired_on}
                      onChange={(event) =>
                        setEnrollForm({
                          ...enrollForm,
                          expired_on: event.target.value,
                        })
                      }
                      className="w-full h-11 rounded-xl border border-[#143DAA]/20 px-3.5 text-sm text-[#143DAA] outline-none focus:border-[#143DAA] focus:ring-2 focus:ring-[#143DAA]/10"
                    />
                  </div>
                </div>
              </div>

              <div className="border-t border-[#143DAA]/10 pt-4">
                <h3 className="text-sm font-bold text-[#143DAA] mb-3">
                  {tr("enrollment.presentAddress", "Present Address", "អាសយដ្ឋានបច្ចុប្បន្ន")}
                </h3>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-semibold text-[#143DAA] mb-1.5">
                      {tr("enrollment.houseNo", "House No.", "លេខផ្ទះ")}
                    </label>
                    <input
                      type="text"
                      value={enrollForm.house_no}
                      onChange={(event) =>
                        setEnrollForm({
                          ...enrollForm,
                          house_no: event.target.value,
                        })
                      }
                      className="w-full h-11 rounded-xl border border-[#143DAA]/20 px-3.5 text-sm text-[#143DAA] outline-none focus:border-[#143DAA] focus:ring-2 focus:ring-[#143DAA]/10"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-semibold text-[#143DAA] mb-1.5">
                      {tr("enrollment.village", "Village", "ភូមិ")}
                    </label>
                    <input
                      type="text"
                      value={enrollForm.village}
                      onChange={(event) =>
                        setEnrollForm({
                          ...enrollForm,
                          village: event.target.value,
                        })
                      }
                      className="w-full h-11 rounded-xl border border-[#143DAA]/20 px-3.5 text-sm text-[#143DAA] outline-none focus:border-[#143DAA] focus:ring-2 focus:ring-[#143DAA]/10"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-semibold text-[#143DAA] mb-1.5">
                      {tr("enrollment.communeSangkat", "Commune / Sangkat", "ឃុំ / សង្កាត់")}
                    </label>
                    <input
                      type="text"
                      value={enrollForm.commune_sangkat}
                      onChange={(event) =>
                        setEnrollForm({
                          ...enrollForm,
                          commune_sangkat: event.target.value,
                        })
                      }
                      className="w-full h-11 rounded-xl border border-[#143DAA]/20 px-3.5 text-sm text-[#143DAA] outline-none focus:border-[#143DAA] focus:ring-2 focus:ring-[#143DAA]/10"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-semibold text-[#143DAA] mb-1.5">
                      {tr("enrollment.districtKhan", "District / Khan", "ស្រុក / ខណ្ឌ")}
                    </label>
                    <input
                      type="text"
                      value={enrollForm.district_khan}
                      onChange={(event) =>
                        setEnrollForm({
                          ...enrollForm,
                          district_khan: event.target.value,
                        })
                      }
                      className="w-full h-11 rounded-xl border border-[#143DAA]/20 px-3.5 text-sm text-[#143DAA] outline-none focus:border-[#143DAA] focus:ring-2 focus:ring-[#143DAA]/10"
                    />
                  </div>

                  <div className="md:col-span-2">
                    <label className="block text-sm font-semibold text-[#143DAA] mb-1.5">
                      {tr("enrollment.provinceCity", "Province / City", "រាជធានី / ខេត្ត")}
                    </label>
                    <input
                      type="text"
                      value={enrollForm.province_city}
                      onChange={(event) =>
                        setEnrollForm({
                          ...enrollForm,
                          province_city: event.target.value,
                        })
                      }
                      className="w-full h-11 rounded-xl border border-[#143DAA]/20 px-3.5 text-sm text-[#143DAA] outline-none focus:border-[#143DAA] focus:ring-2 focus:ring-[#143DAA]/10"
                    />
                  </div>
                </div>
              </div>

              <div className="border-t border-[#143DAA]/10 pt-4">
                <h3 className="text-sm font-bold text-[#143DAA] mb-3">
                  {tr("enrollment.contactInfo", "Contact Information", "ព័ត៌មានទំនាក់ទំនង")}
                </h3>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-semibold text-[#143DAA] mb-1.5">
                      {tr("enrollment.phone", "Phone", "លេខទូរស័ព្ទ")}
                    </label>
                    <input
                      type="tel"
                      value={enrollForm.phone}
                      onChange={(event) =>
                        setEnrollForm({
                          ...enrollForm,
                          phone: event.target.value,
                        })
                      }
                      className="w-full h-11 rounded-xl border border-[#143DAA]/20 px-3.5 text-sm text-[#143DAA] outline-none focus:border-[#143DAA] focus:ring-2 focus:ring-[#143DAA]/10"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-semibold text-[#143DAA] mb-1.5">
                      {tr("enrollment.email", "Email", "អ៊ីមែល")} *
                    </label>
                    <input
                      type="email"
                      value={enrollForm.email}
                      onChange={(event) =>
                        setEnrollForm({
                          ...enrollForm,
                          email: event.target.value,
                        })
                      }
                      className="w-full h-11 rounded-xl border border-[#143DAA]/20 px-3.5 text-sm text-[#143DAA] outline-none focus:border-[#143DAA] focus:ring-2 focus:ring-[#143DAA]/10"
                      required
                    />
                  </div>
                </div>
              </div>

              {/* BUTTONS */}
              <div className="pt-2 flex flex-col-reverse sm:flex-row sm:justify-end gap-3">
                {/* CANCEL */}
                <button
                  type="button"
                  onClick={closeEnrollModal}
                  disabled={enrollSubmitting}
                  className="h-11 px-5 rounded-xl border border-[#143DAA]/20 bg-white text-sm font-bold text-[#1F2937] hover:bg-[#F8FAFC] transition disabled:opacity-50"
                >
                  {tr("enrollment.cancel", "Cancel", "បោះបង់")}
                </button>

                {/* SUBMIT */}
                <button
                  type="submit"
                  disabled={enrollSubmitting}
                  className="h-11 px-5 rounded-xl bg-[#EF233C] text-sm font-bold text-white hover:bg-[#D91A2A] transition disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {enrollSubmitting
                    ? tr("enrollment.submitting", "Submitting...", "កំពុងផ្ញើ...")
                    : tr("enrollment.submit", "Submit Enrollment", "ផ្ញើការចុះឈ្មោះ")}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </>
  );
};

export default Courses;
